{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Mithramycin, a large glycosylated polyketide with multiple sugars and polar groups, showed a peak CSF:plasma ratio of only 0.12 in monkeys and little brain distribution, directly indicating that this class of highly glycosylated aromatic natural products does not achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, another glycosylated natural product with multiple sugar residues, had a very low CSF/plasma ratio of 0.01-0.03 in dogs, demonstrating impermeable BBB penetration and supporting poor CNS access for large polar glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Doxycycline, a polycyclic antibiotic with multiple H-bond donors and acceptors, showed only traces crossing the BBB in rats; the query shares the polycyclic aromatic polar pharmacophore and ionizable groups, supporting a fail prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Gentamicin, an aminoglycoside with multiple amino and hydroxy groups, was not detected in CSF after systemic administration; the query contains an amino sugar and many polar groups, so similar CNS exclusion is expected.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "CMT-3, a lipophilic chemically modified tetracycline, showed brain accumulation of 4 µg/g in rats, indicating that some tetracycline-related scaffolds can penetrate; however, its much lower polarity and smaller size limit transfer to the query, so this does not override the dominant poor-penetration evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, highly polar glycosylated anthracycline with multiple H-bond donors/acceptors and an ionizable amino sugar. Direct evidence from structurally related glycosylated and polar polycyclic natural products (mithramycin, digitoxin, doxycycline, gentamicin) consistently shows poor or absent CNS penetration. The single permeable tetracycline analogue is much less polar and does not transfer. Therefore, meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule.",
    "No human pharmacokinetic data for the query or a close analogue.",
    "Efflux transporter profile of the query is not experimentally confirmed.",
    "Computed physicochemical properties are used only as an uncertain prior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

